function validatePolicy(policy: RetentionPolicy): void {
  if (policy.maxAgeDays !== undefined && policy.maxAgeDays < 0) {
    throw new Error(
      `Invalid retention policy: maxAgeDays must be non-negative, got ${policy.maxAgeDays}`,
    );
  }
  if (
